const formatConversationDate=(value:string)=>{const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const now=new Date();return d.toDateString()===now.toDateString()?d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):d.toLocaleDateString([],{year:'2-digit',month:'2-digit',day:'2-digit'});};
const formatLastSeen=(value:string)=>{const t=new Date(value).getTime();if(Number.isNaN(t))return '';const m=Math.max(0,Math.floor((Date.now()-t)/60000));if(m<1)return 'just now';if(m<2)return '1 minute ago';if(m<3)return '2 minutes ago';if(m<5)return '3 minutes ago';if(m<15)return '5 minutes ago';if(m<45)return 'half an hour ago';if(m<90)return '1 hour ago';const h=Math.floor(m/60);if(h<24)return (h<2?'2':String(h))+' hours ago';const d=Math.floor(h/24);if(d<7)return d===1?'1 day ago':d+' days ago';if(d<14)return '1 week ago';if(d<30)return Math.floor(d/7)+' weeks ago';if(d<60)return '1 month ago';if(d<90)return '2 months ago';return 'a long time ago';};
