 const load=useCallback((): Promise<void>=>{
  if(loadInFlight.current){loadAgain.current=true;return loadInFlight.current;}
  const run=async()=>{
   const {data:{session}}=await supabase.auth.getSession();
   const uid=session?.user?.id;
   if(!uid){setLoading(false);return;}
   setCurrentUserId(prev=>prev===uid?prev:uid);
   if(!hasLoaded.current){try{const saved=await AsyncStorage.getItem('wantiss.message-drafts.'+uid);setDrafts(saved?JSON.parse(saved):{});}catch{setDrafts({});}}
   const {data,error:queryError}=await supabase.from('conversations').select('id,title,participant_ids,updated_at,feature,ref_id,business_id,customer_id').contains('participant_ids',[uid]).order('updated_at',{ascending:false});
   if(queryError){if(!hasLoaded.current)setError(queryError.message);setLoading(false);return;}
   const rows=((data||[]) as Conversation[]).filter(c=>!c.business_id||c.customer_id===uid);
   const friendIds=Array.from(new Set(rows.filter(c=>c.feature==='friends').flatMap(c=>c.participant_ids||[]).filter(id=>id!==uid)));
   const storeIds=Array.from(new Set(rows.filter(c=>c.feature==='goodies'&&c.ref_id).map(c=>c.ref_id as string)));
   const groupIds=rows.filter(c=>c.feature==='group').map(c=>c.id);
   const needProfiles=friendIds.some(id=>!profileCache.current[id]&&!profilesTried.current.has(id));
   const needCovers=storeIds.some(id=>!(id in coverCache.current));
   // Everything the list needs is fetched together, then applied in one pass so the inbox never half-renders.
   const [profilesRes,storesRes,latestRes,statesRes,countsRes]=await Promise.all([
    needProfiles?supabase.rpc('wantiss_message_contact_profiles'):Promise.resolve(null),
    needCovers?supabase.from('goodies_store_schedules').select('store_id,cover_url,thumbnail_url,logo_url').in('store_id',storeIds):Promise.resolve(null),
    rows.length?supabase.from('messages').select('id,conversation_id,sender_id,body,created_at').in('conversation_id',rows.map(x=>x.id)).order('created_at',{ascending:false}).limit(1000):Promise.resolve(null),
    groupIds.length?supabase.from('message_participant_state').select('conversation_id,last_read_at').eq('user_id',uid).in('conversation_id',groupIds):Promise.resolve(null),
    rows.length?supabase.rpc('wantiss_unread_message_counts'):Promise.resolve(null)
   ]);
   if(profilesRes){if(profilesRes.error)console.warn('Friend profiles could not load:',profilesRes.error.message);else{(profilesRes.data||[]).forEach((p:any)=>{profileCache.current[p.id]={full_name:p.full_name,avatar_url:p.avatar_url,wantiss_number:p.wantiss_number};});friendIds.forEach(id=>profilesTried.current.add(id));}}
   if(storesRes){if(storesRes.error)console.warn('Store cover photos could not load:',storesRes.error.message);else{storeIds.forEach(id=>{coverCache.current[id]='';});(storesRes.data||[]).forEach((s:any)=>{const uri=s.thumbnail_url||s.logo_url||s.cover_url;if(uri)coverCache.current[s.store_id]=uri;});}}
   const covers:Record<string,string>={};storeIds.forEach(id=>{if(coverCache.current[id])covers[id]=coverCache.current[id];});
   const latest=((latestRes?.data||[]) as Message[]);
   const previews:Record<string,Message>={};latest.forEach(m=>{if(!previews[m.conversation_id])previews[m.conversation_id]=m;});
   const counts:Record<string,number>={};
   ((countsRes?.data||[]) as any[]).forEach(m=>{if(rows.some(c=>c.id===m.conversation_id))counts[m.conversation_id]=Number(m.unread_count)||0;});
   const cursors:Record<string,string|null>=Object.fromEntries(((statesRes?.data||[]) as any[]).map(x=>[x.conversation_id,x.last_read_at]));
   groupIds.forEach(id=>{const cursor=cursors[id]||'1970-01-01T00:00:00Z';counts[id]=latest.filter(m=>m.conversation_id===id&&m.sender_id!==uid&&m.created_at>cursor).length;});
   hasLoaded.current=true;
   setItems(prev=>same(prev,rows)?prev:rows);
   setContactProfiles(prev=>{const next={...prev,...profileCache.current};return same(prev,next)?prev:next;});
   setStoreCovers(prev=>same(prev,covers)?prev:covers);
   setLastMessages(prev=>same(prev,previews)?prev:previews);
   setUnread(prev=>same(prev,counts)?prev:counts);
   setError('');setLoading(false);
  };
  const promise=run().catch(e=>{console.warn('Messages could not load:',e);setLoading(false);}).finally(()=>{loadInFlight.current=null;if(loadAgain.current){loadAgain.current=false;void loadRef.current();}});
  loadInFlight.current=promise;return promise;
 },[]);
